/**
 * PDF import (note 13) on real plotting-library output, generated by
 * `scripts/pdf-fixtures/`: matplotlib 3.11 with its default Type 3 fonts and
 * with `pdf.fonttype` 42 (embedded TrueType), a two-page `PdfPages` file
 * (bars; a heatmap drawn as an image), base R's `pdf()` (standard Helvetica,
 * not embedded) and ggplot2 through `cairo_pdf()` (embedded subset fonts).
 * `handmade.pdf` holds the features plots rarely use, written as raw PDF.
 * pdf.js runs here in Node, as it does in the browser minus the worker.
 */
import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { type SvgNode, nodeToSvgString, walkNodes } from '@/render/svgNode';

import { type Imported, importFile, importPdf } from '../import';
import { sanitizeSvg } from '../svg/sanitize';
import { PdfImportError, openPdf } from './loadPdf';
import {
  MAX_IMAGE_RECTS,
  type PdfFont,
  type PdfPageInput,
  clipPolyline,
  clipRing,
  imageRects,
  pageToSvg,
  pdfFontStyle,
  unmappable,
} from './pageToSvg';

const bytes = (name: string): Uint8Array<ArrayBuffer> =>
  new Uint8Array(readFileSync(new URL(`./fixtures/${name}.pdf`, import.meta.url)));

async function imported(name: string, page = 1): Promise<Imported> {
  const imp = await importPdf(bytes(name), `${name}.pdf`, () => Promise.resolve(page));
  if (!imp) throw new Error('cancelled');
  return imp;
}

const svgOf = (imp: Imported): string => (imp.asset.kind === 'svgImport' ? imp.asset.svg : '');
const tree = (imp: Imported): SvgNode => sanitizeSvg(svgOf(imp)).root;
const all = (root: SvgNode): SvgNode[] => [...walkNodes(root)].slice(1);
const texts = (root: SvgNode): SvgNode[] => all(root).filter((n) => n.tag === 'text');
const label = (n: SvgNode): string =>
  n.children.map((c) => (typeof c === 'string' ? c : label(c))).join('');
const labels = (imp: Imported): string[] => texts(tree(imp)).map(label);
const viewBox = (imp: Imported): number[] =>
  (/viewBox="([^"]+)"/.exec(svgOf(imp))?.[1] ?? '').split(' ').map(Number);

/** The export subset (CLAUDE.md, note 03). */
const TAGS = new Set(['g', 'path', 'rect', 'ellipse', 'circle', 'line', 'polyline', 'polygon']);
TAGS.add('text').add('tspan');

const FIXTURES = ['matplotlib-type3', 'matplotlib-truetype', 'r-pdf', 'r-cairo'] as const;

describe('real plots', () => {
  for (const name of FIXTURES) {
    it(`${name}: stays in the export subset and re-sanitises to itself`, async () => {
      const imp = await imported(name);
      const root = tree(imp);
      for (const n of all(root)) expect(TAGS.has(n.tag), n.tag).toBe(true);
      expect(nodeToSvgString(sanitizeSvg(nodeToSvgString(root)).root)).toBe(nodeToSvgString(root));
      expect(imp.asset.kind === 'svgImport' && imp.asset.meta.name).toBe(`${name}.pdf`);
    });
  }

  it('matplotlib: the same labels as real text with Type 3 and TrueType fonts', async () => {
    const t3 = await imported('matplotlib-type3');
    const tt = await imported('matplotlib-truetype');
    const expected = [
      '0.0',
      '2.5',
      '5.0',
      '7.5',
      '10.0',
      'Time (s)',
      '−1.0', // matplotlib writes − as a run of its own: joined back
      '−0.5',
      '0.0',
      '0.5',
      '1.0',
      'Signal μV', // mathtext: one run per symbol, joined into one label (note 15)
      'Two waves',
      'sin',
      'cos',
    ];
    expect(labels(t3)).toEqual(expected);
    expect(labels(tt)).toEqual(expected);
    expect(t3.warnings).toEqual([]);
    expect(svgOf(t3)).toBe(svgOf(tt));
    const t = texts(tree(t3));
    const title = t.find((n) => label(n) === 'Two waves');
    expect(title?.attrs['font-family']).toBe('DejaVu Sans, sans-serif');
    // 12 pt is 16 px, the SVG default, so it is not written.
    expect(title?.attrs['font-size']).toBeUndefined();
    expect(t.find((n) => label(n) === 'sin')?.attrs['font-size']).toBe('9.333'); // 7 pt
    const yLabel = t.find((n) => label(n) === 'Signal μV');
    expect(yLabel?.children).toEqual([
      'Signal ',
      { tag: 'tspan', attrs: { 'font-style': 'italic' }, children: ['μ'] },
      'V',
    ]);
    expect(yLabel?.attrs['transform']).toMatch(/^rotate\(-90 /);
  });

  it('matplotlib: the white page goes, the axes are cropped to, and lines are clipped', async () => {
    const imp = await imported('matplotlib-type3');
    const [x, y, w, h] = viewBox(imp);
    // The page is 230.4 × 172.8 pt (307.2 × 230.4 px); the drawing is smaller.
    expect(w).toBeLessThan(300);
    expect(h).toBeLessThan(225);
    const root = tree(imp);
    const whiteRects = all(root).filter((n) => n.attrs['fill'] === '#ffffff');
    // The axes patch stays (it is not page-sized); the figure patch is gone.
    expect(whiteRects.length).toBe(2); // axes patch and legend box
    // The cos curve runs off the axes in the PDF and is clipped there: no
    // point of any dashed path lies outside the axes box.
    const dashed = all(root).filter((n) => n.attrs['stroke-dasharray'] !== undefined);
    expect(dashed.length).toBeGreaterThan(0);
    const axes = { y0: 34.5, y1: 174.7 };
    for (const n of dashed) {
      const ys = [...String(n.attrs['d']).matchAll(/[ML][\d.]+ ([\d.]+)/g)].map((m) =>
        Number(m[1]),
      );
      for (const v of ys) {
        expect(v).toBeGreaterThanOrEqual(axes.y0);
        expect(v).toBeLessThanOrEqual(axes.y1);
      }
    }
    expect(x).toBeGreaterThan(0);
    expect(y).toBeGreaterThan(0);
  });

  it('base R pdf(): standard Helvetica (not embedded) as text, dashes and rotation kept', async () => {
    const imp = await imported('r-pdf');
    expect(labels(imp)).toEqual(
      expect.arrayContaining(['Base R', 'Dose (mg)', 'Response', 'obs', 'fit', '25', '10']),
    );
    const t = texts(tree(imp));
    const title = t.find((n) => label(n) === 'Base R');
    expect(title?.attrs['font-family']).toBe('Helvetica, sans-serif');
    expect(title?.attrs['font-weight']).toBe('bold');
    expect(t.find((n) => label(n) === 'Response')?.attrs['transform']).toMatch(/^rotate\(-90 /);
    const dashed = all(tree(imp)).filter((n) => n.attrs['stroke-dasharray'] !== undefined);
    expect(dashed.map((n) => n.attrs['stroke'])).toContain('#d55e00');
    expect(imp.warnings).toEqual([]);
  });

  it('ggplot2 cairo_pdf(): embedded subset font named without its prefix', async () => {
    const imp = await imported('r-cairo');
    expect(labels(imp)).toEqual(
      expect.arrayContaining(['ggplot2', 'ctrl', 'drug A', 'drug B', 'Treatment', 'Expression']),
    );
    const t = texts(tree(imp));
    expect(t[0]?.attrs['font-family']).toBe('Liberation Sans, sans-serif');
    // The three bars keep ggplot2's hue palette.
    const fills = new Set(all(tree(imp)).map((n) => n.attrs['fill']));
    for (const c of ['#f8766d', '#00ba38', '#619cff']) expect(fills.has(c), c).toBe(true);
  });
});

describe('pages', () => {
  it('asks which page of a multi-page file to import, with sizes in points', async () => {
    let asked: readonly { number: number; width: number; height: number }[] = [];
    const imp = await importPdf(bytes('matplotlib-pages'), 'two.pdf', (pages) => {
      asked = pages;
      return Promise.resolve(1);
    });
    expect(asked).toEqual([
      { number: 1, width: 172.8, height: 144 },
      { number: 2, width: 172.8, height: 144 },
    ]);
    expect(labels(imp!)).toEqual(expect.arrayContaining(['A', 'B', 'C', 'Count']));
    expect(imp!.asset.kind === 'svgImport' && imp!.asset.meta.name).toBe('two.pdf (page 1)');
  });

  it('a cancelled choice imports nothing; without a chooser the first page is taken', async () => {
    expect(await importPdf(bytes('matplotlib-pages'), 'x.pdf', () => Promise.resolve(null))).toBe(
      null,
    );
    expect(labels((await importPdf(bytes('matplotlib-pages'), 'x.pdf'))!)).toContain('Count');
  });

  it('the chooser can preview any page before choosing', async () => {
    const imp = await importPdf(bytes('matplotlib-pages'), 'x.pdf', async (_pages, preview) => {
      expect(labels(await preview(2))).toContain('Heatmap');
      return 1;
    });
    expect(labels(imp!)).toContain('Count');
  });

  it('a small block image (a heatmap) becomes one rectangle per cell', async () => {
    const imp = await imported('matplotlib-pages', 2);
    expect(imp.warnings).toEqual([]);
    const fills = all(tree(imp))
      .filter((n) => n.tag === 'path' && n.attrs['fill'] && n.attrs['fill'] !== '#ffffff')
      .map((n) => n.attrs['fill']);
    // viridis 4 × 4: 16 colours.
    expect(new Set(fills).size).toBeGreaterThanOrEqual(16);
  });
});

describe('handmade PDF features', () => {
  it('keeps what it can and says what it changed', async () => {
    const imp = await imported('handmade');
    const root = tree(imp);
    expect(labels(imp)).toEqual(['Rotated']); // the invisible "hidden" is not
    const rotated = texts(root)[0];
    expect(rotated?.attrs['transform']).toMatch(/^rotate\(-30(\.00\d)? /);
    expect(rotated?.attrs['font-size']).toBe('13.333'); // 10 pt
    const paths = all(root).filter((n) => n.tag === 'path' || n.tag === 'rect');
    expect(paths.some((n) => n.attrs['fill-rule'] === 'evenodd')).toBe(true);
    expect(paths.some((n) => n.attrs['fill-opacity'] === '0.5')).toBe(true);
    expect(paths.some((n) => n.attrs['stroke-dasharray'] === '5.333 2.667')).toBe(true);
    // The 3 × 2 image: six cells in six colours.
    for (const c of ['#ff0000', '#00ff00', '#0000ff', '#ffff00'])
      expect(
        paths.some((n) => n.attrs['fill'] === c),
        c,
      ).toBe(true);
    expect(imp.warnings).toEqual([
      'A clipping shape that is not a rectangle was approximated by a rectangle.',
      'Text whose letters have no known meaning was kept as letter shapes.',
    ]);
  });
});

describe('files', () => {
  it('importFile routes a PDF by name, type or content', async () => {
    const data = bytes('r-pdf');
    for (const f of [
      new File([data], 'plot.pdf'),
      new File([data], 'plot', { type: 'application/pdf' }),
      new File([data], 'plot.bin'),
    ]) {
      const imp = await importFile(f);
      expect(imp?.asset.kind).toBe('svgImport');
    }
  });

  it('something that is not a PDF is reported as such', async () => {
    await expect(openPdf(new TextEncoder().encode('%PDF-1.4 nonsense'))).rejects.toThrow(
      PdfImportError,
    );
  });
});

// ---- The converter on its own ---------------------------------------------------

const OPS = {
  save: 10,
  restore: 11,
  transform: 12,
  clip: 29,
  beginText: 31,
  setFont: 37,
  moveText: 40,
  showText: 44,
  setFillRGBColor: 59,
  constructPath: 91,
  fill: 22,
  stroke: 20,
  endPath: 28,
};

function convert(
  ops: [keyof typeof OPS, unknown[]][],
  extra: Partial<PdfPageInput> = {},
): { svg: string; warnings: readonly string[] } {
  return pageToSvg({
    ops: { fnArray: ops.map(([n]) => OPS[n]), argsArray: ops.map(([, a]) => a) },
    OPS,
    width: 100,
    height: 100,
    viewport: [1, 0, 0, -1, 0, 100],
    font: () => null,
    glyphPath: () => null,
    ...extra,
  });
}

const rect = (x: number, y: number, w: number, h: number): number[] => [
  0,
  x,
  y,
  1,
  x + w,
  y,
  1,
  x + w,
  y + h,
  1,
  x,
  y + h,
  4,
];
const glyph = (unicode: string, fontChar = unicode, width = 500) => ({
  unicode,
  fontChar,
  width,
  isSpace: unicode === ' ',
  isInFont: true,
});

describe('pageToSvg', () => {
  const font: PdfFont = { name: 'ABCDEF+Arial-BoldMT', loadedName: 'f1', bold: true };

  it('flips PDF space into SVG space and keeps colours', () => {
    const { svg } = convert([
      ['setFillRGBColor', ['#123456']],
      ['constructPath', [OPS.fill, [rect(10, 10, 20, 30)], null]],
    ]);
    expect(svg).toContain('<path d="M10 90L30 90L30 60L10 60Z" fill="#123456"/>');
  });

  it('clips a straddling line to the clip rectangle and drops what lies outside', () => {
    const { svg } = convert([
      ['clip', []],
      ['constructPath', [OPS.endPath, [rect(0, 0, 50, 50)], null]],
      ['constructPath', [OPS.stroke, [[0, -10, 25, 1, 100, 25]], null]],
      ['constructPath', [OPS.fill, [rect(60, 60, 10, 10)], null]],
    ]);
    expect(svg).toContain('d="M0 75L50 75"');
    expect(svg).not.toContain('M60');
  });

  it('draws text with a run of its own per gap, joined when runs touch', () => {
    const { svg } = convert(
      [
        ['beginText', []],
        ['setFont', ['f1', 10]],
        ['moveText', [10, 20]],
        ['showText', [[glyph('a'), glyph('b'), -2000, glyph('c')]]],
        ['showText', [[glyph('d'), -200, glyph('e')]]],
      ],
      { font: () => font },
    );
    const t = [...svg.matchAll(/<text[^>]*>([^<]*)<\/text>/g)].map((m) => m[1]);
    expect(t).toEqual(['ab', 'cd e']);
    expect(svg).toContain('font-family="Arial, sans-serif" font-weight="bold"');
    expect(svg).toContain('transform="matrix(10 0 0 10 10 80)"');
  });

  it('draws a run with a letter of unknown meaning as the font’s outlines', () => {
    const { svg, warnings } = convert(
      [
        ['beginText', []],
        ['setFont', ['f1', 10]],
        ['showText', [[glyph('', 'x'), glyph('b')]]],
      ],
      { font: () => font, glyphPath: () => rect(0, 0, 0.5, 0.7) },
    );
    expect(svg).not.toContain('<text');
    expect(svg.match(/<path/g)?.length).toBe(2);
    expect(svg).toContain('M0 100L5 100L5 93L0 93Z');
    expect(warnings).toEqual([
      'Text whose letters have no known meaning was kept as letter shapes.',
    ]);
  });

  it('knows which letters have no meaning', () => {
    expect(unmappable('A')).toBe(false);
    expect(unmappable('−')).toBe(false);
    expect(unmappable('')).toBe(true);
    expect(unmappable('\u0001')).toBe(true);
    expect(unmappable('')).toBe(true);
    expect(unmappable('�')).toBe(true);
  });

  it('names fonts from their PostScript names', () => {
    expect(pdfFontStyle(font)).toEqual({ family: 'Arial, sans-serif', weight: 'bold' });
    expect(pdfFontStyle({ name: 'TimesNewRomanPSMT' }).family).toBe('Times New Roman, serif');
    expect(pdfFontStyle({ name: 'Helvetica-Oblique', italic: true })).toEqual({
      family: 'Helvetica, sans-serif',
      style: 'italic',
    });
    expect(pdfFontStyle({ name: '', fallbackName: 'serif' }).family).toBe('serif');
  });
});

describe('geometry', () => {
  it('clips a ring to a rectangle (Sutherland–Hodgman)', () => {
    const ring = clipRing(
      [
        [-10, -10],
        [10, -10],
        [10, 10],
        [-10, 10],
      ],
      [0, 0, 20, 20],
    );
    expect(ring).toEqual([
      [0, 0],
      [10, 0],
      [10, 10],
      [0, 10],
    ]);
  });

  it('clips a polyline into its visible pieces (Liang–Barsky)', () => {
    const pieces = clipPolyline(
      [
        [-5, 5],
        [5, 5],
        [5, 15],
        [5, 25],
        [15, 25],
        [15, 5],
      ],
      [0, 0, 20, 20],
    );
    expect(pieces).toEqual([
      [
        [0, 5],
        [5, 5],
        [5, 15],
        [5, 20],
      ],
      [
        [15, 20],
        [15, 5],
      ],
    ]);
  });

  it('turns block images into rectangles, but not detailed ones', () => {
    const img = { width: 2, height: 2, kind: 2, data: [1, 2, 3, 1, 2, 3, 9, 9, 9, 1, 2, 3] };
    const rects = imageRects(img);
    expect(rects?.map(([c, a]) => [c, a])).toEqual([
      ['#010203', 1],
      ['#090909', 1],
    ]);
    // Row 1 (top) is one run, merged with the right half of row 2.
    expect(rects?.[0]?.[2].length).toBe(26);
    const noise = Array.from({ length: 200 * 200 * 3 }, (_, i) => (i * 7919) % 251);
    expect(imageRects({ width: 200, height: 200, kind: 2, data: noise })).toBe(null);
    expect(MAX_IMAGE_RECTS).toBeLessThan(200 * 200);
    expect(imageRects({ width: 1, height: 1, kind: 1, data: [0] })).toBe(null);
  });
});
